* {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
}

.ds-app {
 max-width: 1600px;
 margin: 0 auto;
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 24px;
 background: #0a0e1a;
 min-height: 100vh;
 color: #e2e8f0;
 font-family: system-ui, -apple-system, sans-serif;
}

/* Card base class */
.ds-card {
 background: #131a2e;
 border: 1px solid #1e2a45;
 border-radius: 14px;
 padding: 24px;
 box-shadow: 0 0 20px rgba(0, 200, 150, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

/* Section title */
.ds-section-title {
 font-size: 11px;
 font-weight: 700;
 letter-spacing: 1.5px;
 text-transform: uppercase;
 color: #94a3b8;
 margin-bottom: 16px;
}

/* Row layouts */
.ds-row {
 display: grid;
 gap: 24px;
}

.ds-row--2col {
 grid-template-columns: 1fr 1fr;
}

.ds-row--3col {
 grid-template-columns: 1fr 1fr 1fr;
}

/* Badge styles */
.ds-badge {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 padding: 4px 12px;
 border-radius: 20px;
 font-size: 11px;
 font-weight: 600;
 letter-spacing: 0.5px;
}

.ds-badge--green {
 background: rgba(0, 200, 150, 0.12);
 color: #00c896;
 border: 1px solid rgba(0, 200, 150, 0.3);
}

.ds-badge--orange {
 background: rgba(245, 158, 11, 0.12);
 color: #f59e0b;
 border: 1px solid rgba(245, 158, 11, 0.3);
}

.ds-badge--red {
 background: rgba(239, 68, 68, 0.12);
 color: #ef4444;
 border: 1px solid rgba(239, 68, 68, 0.3);
}

.ds-badge--blue {
 background: rgba(59, 130, 246, 0.12);
 color: #3b82f6;
 border: 1px solid rgba(59, 130, 246, 0.3);
}

.ds-badge--purple {
 background: rgba(139, 92, 246, 0.12);
 color: #8b5cf6;
 border: 1px solid rgba(139, 92, 246, 0.3);
}

/* Progress bar base */
.ds-progress {
 height: 6px;
 background: rgba(30, 42, 69, 0.8);
 border-radius: 3px;
 overflow: hidden;
}

.ds-progress__fill {
 height: 100%;
 border-radius: 3px;
 transition: width 0.6s ease;
}

.ds-progress__fill--green {
 background: linear-gradient(90deg, #00c896, #00e6ac);
}

.ds-progress__fill--blue {
 background: linear-gradient(90deg, #3b82f6, #60a5fa);
}

.ds-progress__fill--orange {
 background: linear-gradient(90deg, #f59e0b, #fbbf24);
}

.ds-progress__fill--red {
 background: linear-gradient(90deg, #ef4444, #f87171);
}

/* Animations */
@keyframes ds-pulse {
 0%, 100% {
 opacity: 1;
 transform: scale(1);
 }
 50% {
 opacity: 0.5;
 transform: scale(1.3);
 }
}
@keyframes ds-fade-in {
 from {
 opacity: 0;
 transform: translateY(8px);
 }
 to {
 opacity: 1;
 transform: translateY(0);
 }
}
@keyframes ds-blink {
 0%, 100% {
 opacity: 1;
 }
 50% {
 opacity: 0.6;
 }
}
@keyframes ds-gauge-fill {
 from {
 stroke-dashoffset: 565;
 }
}
.ds-app .fade-in {
 animation: ds-fade-in 0.4s ease-out forwards;
}

/* Scrollbar */
.ds-app ::-webkit-scrollbar {
 width: 6px;
}

.ds-app ::-webkit-scrollbar-track {
 background: #0a0e1a;
}

.ds-app ::-webkit-scrollbar-thumb {
 background: #1e2a45;
 border-radius: 3px;
}

/* Responsive */
@media (max-width: 1200px) {
 .ds-row--2col {
 grid-template-columns: 1fr;
 }
